// Print edition: verified course summaries and professor-aligned print revisions.
export const printEdition={"overrides":{"C05-2":{"concepts":[{"id":"C05-2-concept-1","term":"컴퓨팅 선택","english":"VM · App Service · Functions","ex":[1],"text":"VM은 OS와 앱을 직접 제어하고, App Service는 웹·API 호스팅 플랫폼, Functions는 이벤트 기반 함수 실행을 제공한다. 서버리스는 서버 운영을 제공받는 방식이고 무상태는 이전 요청의 상태를 실행 환경에 보존하지 않고 각 요청을 독립 처리하는 설계다. 서버리스 앱도 외부 DB·저장소에 상태를 유지할 수 있다.","sourceIds":["DC-run-C05-2-ex1"],"locator":"직접 확인한 DataCamp 수업 / ex=1","claimId":"C05-2-expanded-1","contentType":"DataCamp 강의 확인 내용"},{"id":"C05-2-concept-2","term":"패키징·조율·마이크로서비스","english":"Container · Kubernetes · AKS · ACI · Container Apps","ex":[5],"text":"컨테이너 이미지는 앱과 의존성을 묶은 배포물이다. ACR은 이미지 보관, ACI는 컨테이너를 간단히 실행, AKS는 Kubernetes 클러스터 운영, Container Apps는 플랫폼이 조율하는 컨테이너 앱 운영에 연결한다. 단기 실행·세밀한 클러스터 제어·마이크로서비스 요구를 나누어 비교한다.","sourceIds":["DC-run-C05-2-ex5"],"locator":"직접 확인한 DataCamp 수업 / ex=5","claimId":"C05-2-expanded-2","contentType":"DataCamp 강의 확인 내용"},{"id":"C05-2-concept-3","term":"저장 목적과 구조","english":"Blob · Data Lake · Files · Backup","ex":[9,12],"text":"Blob은 객체, Data Lake는 계층적 데이터 관리, Files는 공유 파일, Backup은 복구 목적에 연결한다. 스토리지 계정에는 Blob·Files·Queue·Table의 저장 단위를 구분한다. 계정·컨테이너·객체는 서로 다른 수준이며 강사 시연은 사용자가 실제 생성했다는 기록이 아니다.","sourceIds":["DC-run-C05-2-ex9","DC-run-C05-2-ex12"],"locator":"직접 확인한 DataCamp 수업 / ex=9, 12","claimId":"C05-2-expanded-3","contentType":"DataCamp 강의 확인 내용"},{"id":"C05-2-concept-4","term":"계층과 중복성","english":"Hot · Cool · Archive · LRS · ZRS · GRS","ex":[9],"text":"계층은 접근 빈도·복원 지연·비용을 비교한다. 중복성은 한 데이터센터·같은 리전의 영역·다른 리전이라는 보호 범위를 비교한다. 저비용 보관 계층과 여러 위치 복제는 다른 목적이고 어느 하나만으로 모든 복구가 보장되지 않는다.","sourceIds":["DC-run-C05-2-ex9"],"locator":"직접 확인한 DataCamp 수업 / ex=9","claimId":"C05-2-expanded-4","contentType":"DataCamp 강의 확인 내용"},{"id":"C05-2-concept-5","term":"실시간·배치와 ETL","english":"Real-time · Batch · ETL","ex":[14],"text":"실시간 처리는 빠른 반영, 배치는 묶음과 주기적 처리 요구에 연결한다. ETL은 추출한 데이터를 정제·변환하여 목적지에 적재하는 흐름이다. 데이터 처리 시점과 변환 과정은 서로 다른 비교 기준이다.","sourceIds":["DC-run-C05-2-ex14"],"locator":"직접 확인한 DataCamp 수업 / ex=14","claimId":"C05-2-expanded-5","contentType":"DataCamp 강의 확인 내용"},{"id":"C05-2-concept-6","term":"분석 도구의 분업","english":"Data Factory · Stream Analytics · Databricks · HDInsight · Synapse","ex":[14],"text":"Data Factory는 워크플로 조율, Stream Analytics는 스트림 쿼리, Databricks는 공동 데이터·ML 작업에 연결한다. HDInsight는 오픈소스 빅데이터 환경, Synapse는 통합 분석의 수업 예다. Synapse와 Fabric을 동일한 제품으로 확정하거나 현재 지원 범위를 이 대본만으로 보장하지 않는다.","sourceIds":["DC-run-C05-2-ex14"],"locator":"직접 확인한 DataCamp 수업 / ex=14","claimId":"C05-2-expanded-6","contentType":"DataCamp 강의 확인 내용"}],"comparisons":[{"title":"같은 앱 안의 서로 다른 선택","ex":[1,5,9,14],"headers":["선택","실행·보관 대상","관리 초점","선택 상황"],"rows":[["VM","가상 서버","OS·앱 관리","OS 직접 제어"],["App Service / Functions","웹·API / 함수","앱·이벤트 코드","호스팅 / 이벤트 실행"],["ACR","컨테이너 이미지","보관·배포물 관리","이미지 저장소 필요"],["ACI","컨테이너 실행","간단한 실행 단위","시험·단기 배치"],["AKS","Kubernetes 클러스터","클러스터 구성·제어","복잡한 운영 요구"],["Container Apps","컨테이너 앱","플랫폼 기반 조율·확장","마이크로서비스"]],"sourceIds":["DC-run-C05-2-ex1","DC-run-C05-2-ex5","DC-run-C05-2-ex9","DC-run-C05-2-ex14"],"locator":"직접 확인한 DataCamp 수업 / ex=1, 5, 9, 14","claimId":"C05-2-expanded-12","contentType":"학습용 비교 재구성"}],"questions":[{"ex":[1,5],"title":"실행 방식과 관리 선택","text":"VM·App Service·Functions·AKS·ACI의 역할과 서버리스·스테이트리스의 차이를 설명하세요.","answer":"VM은 OS·앱 구성을 직접 관리하고 App Service는 웹·API 배포, Functions는 이벤트 기반 코드 실행에 쓴다. ACI는 간단한 컨테이너 실행, AKS는 Kubernetes 클러스터 운영, Container Apps는 플랫폼이 조율하는 컨테이너 앱에 적합하다. 서버리스는 서버 운영 책임, 무상태는 요청 사이의 상태 보존 위치를 구분한다. 서버리스도 외부 DB에 상태를 저장할 수 있으므로 두 용어는 같은 뜻이 아니다.","points":["세 컴퓨팅 모델","컨테이너 조율과 실행","서버리스의 관리 의미","스테이트리스의 상태 의미"],"sourceIds":["DC-run-C05-2-ex1","DC-run-C05-2-ex5"],"locator":"직접 확인한 DataCamp 수업 / ex=1, 5","claimId":"C05-2-expanded-7","contentType":"자체 작성 서술형 예상문제","id":"Q-C05-2-1","modelAnswer":"VM은 OS·버전 제어, App Service는 웹·API 플랫폼, Functions는 이벤트 코드 실행에 연결한다. AKS는 컨테이너 조율, ACI는 컨테이너 실행에 연결한다. 컨테이너 패키징과 조율은 별개다. 서버리스는 기반 서버 관리 추상화이고 스테이트리스는 이전 요청 상태 의존을 줄이는 개념이다. 서버가 없거나 영구 저장소를 쓰지 못한다는 뜻으로 설명하면 안 된다.","version":"2026-10-16-expanded-v1","type":"자체 작성 서술형 예상문제","sourceLocator":"직접 확인한 DataCamp 수업 / ex=1, 5","conceptIds":["C05-2-concept-1","C05-2-concept-2"],"objective":"VM·App Service·Functions·컨테이너를 작업에 맞춰 비교한다.","expectedLength":"핵심 논점 중심 5~7문장","acceptedAlternatives":"동일한 개념·인과관계와 요구를 충족하는 대안 표현을 인정합니다. 서비스 이름만 같은 답은 충분하지 않습니다.","commonMistakes":["서버리스·스테이트리스·컨테이너는 모두 같은 말이다."],"rubric":[{"label":"개념 정확성","max":4},{"label":"원리·인과관계","max":3},{"label":"비교·적용","max":2},{"label":"논리적 구성","max":1}]},{"ex":[9,12],"title":"저장 설계의 여러 기준","text":"파일 보관·공유·복구와 Hot/Cool/Archive·LRS/ZRS/GRS를 분류 기준별로 설명하세요.","answer":"Blob은 객체, Files는 공유 파일, Backup은 복구 목적에 연결한다. 계정과 컨테이너·객체의 수준을 구분해 저장 구조를 설명한다. Hot·Cool·Archive는 접근 빈도·복원 지연·비용을 비교하는 계층이다. LRS·ZRS·GRS는 복제되는 위치와 장애 보호 범위를 비교한다. 계층과 중복성·백업은 서로 다른 요구를 다루며 하나가 나머지를 자동으로 해결하지 않는다.","points":["저장 목적 구분","계정·저장 구조","계층과 접근 조건","복제 위치와 복구 구분"],"sourceIds":["DC-run-C05-2-ex9","DC-run-C05-2-ex12"],"locator":"직접 확인한 DataCamp 수업 / ex=9, 12","claimId":"C05-2-expanded-8","contentType":"자체 작성 서술형 예상문제","id":"Q-C05-2-2","modelAnswer":"Blob은 객체, Files는 공유 파일, Backup은 복구 목적에 연결한다. 계정과 컨테이너·객체의 수준을 구분해 저장 구조를 설명한다. Hot·Cool·Archive는 접근 빈도·복원 지연·비용을 비교하는 계층이다. LRS·ZRS·GRS는 복제되는 위치와 장애 보호 범위를 비교한다. 계층과 중복성·백업은 서로 다른 요구를 다루며 하나가 나머지를 자동으로 해결하지 않는다.","version":"2026-10-16-expanded-v1","type":"자체 작성 서술형 예상문제","sourceLocator":"직접 확인한 DataCamp 수업 / ex=9, 12","conceptIds":["C05-2-concept-3","C05-2-concept-4"],"objective":"저장 형태·계층·복구를 구분한다.","expectedLength":"핵심 논점 중심 5~7문장","acceptedAlternatives":"동일한 개념·인과관계와 요구를 충족하는 대안 표현을 인정합니다. 서비스 이름만 같은 답은 충분하지 않습니다.","commonMistakes":["Archive를 쓰면 복구도 해결되고 ETL은 실시간과 같은 뜻이다."],"rubric":[{"label":"개념 정확성","max":4},{"label":"원리·인과관계","max":3},{"label":"비교·적용","max":2},{"label":"논리적 구성","max":1}]},{"ex":[14],"title":"실시간·배치와 ETL","text":"즉시 반영할 이벤트와 야간 통계의 처리 차이를 설명하고 ETL과 주요 분석 도구를 연결하세요.","answer":"즉시 반영할 이벤트는 실시간, 야간 통계는 주기적으로 묶는 배치 요구로 비교한다. ETL은 추출·정제와 변환·적재의 과정이다. Data Factory는 흐름 조율, Stream Analytics는 스트림 쿼리, Databricks는 공동 데이터·ML 작업에 연결한다. HDInsight와 Synapse도 수업의 빅데이터 환경·통합 분석 예다. 처리 시점과 변환 과정의 축을 구분하고 현재 제품 관계를 이 요약만으로 단정하지 않는다.","points":["반영 지연과 주기 비교","ETL 단계","도구의 역할 분업","처리 시점과 과정 구분"],"sourceIds":["DC-run-C05-2-ex14"],"locator":"직접 확인한 DataCamp 수업 / ex=14","claimId":"C05-2-expanded-9","contentType":"자체 작성 서술형 예상문제","id":"Q-C05-2-3","modelAnswer":"즉시 반영할 이벤트는 실시간, 야간 통계는 주기적으로 묶는 배치 요구로 비교한다. ETL은 추출·정제와 변환·적재의 과정이다. Data Factory는 흐름 조율, Stream Analytics는 스트림 쿼리, Databricks는 공동 데이터·ML 작업에 연결한다. HDInsight와 Synapse도 수업의 빅데이터 환경·통합 분석 예다. 처리 시점과 변환 과정의 축을 구분하고 현재 제품 관계를 이 요약만으로 단정하지 않는다.","version":"2026-10-16-expanded-v1","type":"자체 작성 서술형 예상문제","sourceLocator":"직접 확인한 DataCamp 수업 / ex=14","conceptIds":["C05-2-concept-5","C05-2-concept-6"],"objective":"실시간·배치와 ETL 도구의 역할을 설명한다.","expectedLength":"핵심 논점 중심 5~7문장","acceptedAlternatives":"동일한 개념·인과관계와 요구를 충족하는 대안 표현을 인정합니다. 서비스 이름만 같은 답은 충분하지 않습니다.","commonMistakes":["Archive를 쓰면 복구도 해결되고 ETL은 실시간과 같은 뜻이다."],"rubric":[{"label":"개념 정확성","max":4},{"label":"원리·인과관계","max":3},{"label":"비교·적용","max":2},{"label":"논리적 구성","max":1}]}]},"C06-2":{"concepts":[{"id":"C06-2-concept-1","term":"실행 단위와 플랫폼","english":"VM · App Service · Functions · Containers","ex":[1],"text":"VM은 OS·소프트웨어 고객 관리, App Service 등 PaaS는 플랫폼 부담 감소, Functions는 트리거 실행에 연결한다. ACI는 컨테이너 실행, Registry는 이미지 저장, AKS는 오케스트레이션이다. 컨테이너 전체를 서버리스와 동일시하지 않는다.","sourceIds":["DC-run-C06-2-ex1"],"locator":"직접 확인한 DataCamp 수업 / ex=1","claimId":"C06-2-expanded-1","contentType":"DataCamp 강의 확인 내용"},{"id":"C06-2-concept-2","term":"가상 네트워크","english":"VNet · Subnet · Peering","ex":[4],"text":"VNet 주소 공간을 서브넷으로 나누고 자원 간 경로를 구성한다. 피어링은 VNet 사이 연결, VPN·ExpressRoute는 온프레미스 연결 요구에 연결한다. DNS는 이름 해석이다. 경로·주소와 접근 허용 여부는 서로 다른 설계 요소다.","sourceIds":["DC-run-C06-2-ex4"],"locator":"직접 확인한 DataCamp 수업 / ex=4","claimId":"C06-2-expanded-2","contentType":"DataCamp 강의 확인 내용"},{"id":"C06-2-concept-3","term":"VM 종속 자원","english":"CPU · Memory · OS · Disk · NIC","ex":[8],"text":"VM 크기는 CPU·메모리 요구와 비용에 영향을 준다. OS 디스크와 NIC·VNet은 실행·연결에 필요한 종속 구성을 이룬다. 사설 IP와 Private Endpoint는 동일한 개념이 아니며 인터넷 접속에 VM 자체 공인 IP가 항상 필수라고 설명하지 않는다.","sourceIds":["DC-run-C06-2-ex8"],"locator":"직접 확인한 DataCamp 수업 / ex=8","claimId":"C06-2-expanded-3","contentType":"DataCamp 강의 확인 내용"},{"id":"C06-2-concept-4","term":"수량 확장과 장애 분산","english":"Scale Set · Availability Set","ex":[8],"text":"Scale Set은 VM 수량과 확장 규칙으로 처리 용량을 조정한다. Availability Set은 Fault Domain으로 장비 장애, Update Domain으로 계획 유지보수 영향을 분산한다. Availability Zone은 물리적으로 분리된 영역에 배치한다. 수량 증가·장비 분산·영역 분산은 다른 선택이다.","sourceIds":["DC-run-C06-2-ex8"],"locator":"직접 확인한 DataCamp 수업 / ex=8","claimId":"C06-2-expanded-4","contentType":"DataCamp 강의 확인 내용"},{"id":"C06-2-concept-5","term":"VM 구성 시연의 검증","english":"Configuration · Validation","ex":[11],"text":"VM 생성은 리전·크기·OS·디스크·NIC·VNet을 정하고 검토·유효성 검사를 거친다. 공개 접속은 공인 주소와 접근 규칙, PaaS 사설 접속은 Private Endpoint, VM의 인터넷 송신은 NAT Gateway, App Service의 VNet 자원 호출은 VNet Integration을 비교한다. 송신과 수신의 목적을 구분한다.","sourceIds":["DC-run-C06-2-ex11"],"locator":"직접 확인한 DataCamp 수업 / ex=11","claimId":"C06-2-expanded-5","contentType":"DataCamp 강의 확인 내용"},{"id":"C06-2-concept-6","term":"앱의 역할 분리","english":"Web · API · Background jobs","ex":[13],"text":"App Service의 웹·API·백그라운드 작업·모바일 백엔드를 역할로 이해한다. API는 구현 내부가 아니라 통신 규약을 제공한다. 웹 화면→API→작업→저장과 DB라는 학습용 분해를 사용하되 모든 앱이 VNet 안에 직접 배치되거나 모든 이전이 VM 재호스팅부터 시작한다고 일반화하지 않는다.","sourceIds":["DC-run-C06-2-ex13"],"locator":"직접 확인한 DataCamp 수업 / ex=13","claimId":"C06-2-expanded-6","contentType":"DataCamp 강의 확인 내용"}],"comparisons":[{"title":"컴퓨팅 구조에서 구분할 역할","ex":[1,4,8,13],"headers":["구성","핵심 역할","선택 기준","같지 않은 것"],"rows":[["VM","OS·앱 실행","제어·크기·종속 자원","이미지 저장소"],["App Service","웹·API 플랫폼","개발·운영 범위","모든 OS 제어"],["Registry / ACI / AKS","이미지 저장 / 실행 / 조율","컨테이너 관리 요구","같은 실행 기능 아님"],["VNet / DNS","연결 구조 / 이름 해석","통신 요구","권한 허용과 다름"],["Scale Set / Availability Set","수량 / 장애 영향 분산","수요 / 장애 요구","영역 복제와 구분"]],"sourceIds":["DC-run-C06-2-ex1","DC-run-C06-2-ex4","DC-run-C06-2-ex8","DC-run-C06-2-ex13"],"locator":"직접 확인한 DataCamp 수업 / ex=1, 4, 8, 13","claimId":"C06-2-expanded-12","contentType":"학습용 비교 재구성"}],"questions":[{"ex":[8,11],"title":"VM 구성과 가용성","text":"VM 생성에서 크기·OS·디스크·NIC·VNet·검증의 관계를 설명하고 두 Set을 비교하세요.","answer":"크기는 CPU·메모리와 비용, OS는 실행 환경에 영향을 준다. 디스크는 저장, NIC·VNet은 네트워크 연결에 필요한 종속 구성이다. 관리자 인증·가용성·주소 등을 함께 검토하고 유효성 검사를 확인한다. Scale Set은 수량 조정, Availability Set은 하드웨어 장애·유지보수 영향 분산에 연결한다. 이를 영역 복제나 무중단 보장과 동일시하면 안 된다.","points":["크기·OS의 의미","디스크·NIC·VNet 관계","설정과 검토·검증","두 Set과 가용성 한계"],"sourceIds":["DC-run-C06-2-ex8","DC-run-C06-2-ex11"],"locator":"직접 확인한 DataCamp 수업 / ex=8, 11","claimId":"C06-2-expanded-7","contentType":"자체 작성 서술형 예상문제","id":"Q-C06-2-1","modelAnswer":"크기는 CPU·메모리와 비용, OS는 실행 환경에 영향을 준다. 디스크는 저장, NIC·VNet은 네트워크 연결에 필요한 종속 구성이다. 관리자 인증·가용성·주소 등을 함께 검토하고 유효성 검사를 확인한다. Scale Set은 수량 조정, Availability Set은 하드웨어 장애·유지보수 영향 분산에 연결한다. 이를 영역 복제나 무중단 보장과 동일시하면 안 된다.","version":"2026-10-16-expanded-v1","type":"자체 작성 서술형 예상문제","sourceLocator":"직접 확인한 DataCamp 수업 / ex=8, 11","conceptIds":["C06-2-concept-3","C06-2-concept-4","C06-2-concept-5"],"objective":"VM 종속 자원과 배포 검증을 설명한다.","expectedLength":"핵심 논점 중심 5~7문장","acceptedAlternatives":"동일한 개념·인과관계와 요구를 충족하는 대안 표현을 인정합니다. 서비스 이름만 같은 답은 충분하지 않습니다.","commonMistakes":["VM 인터넷 연결에는 반드시 자체 공인 IP가 필요하며 사설 IP는 Private Endpoint다.","Scale Set과 Availability Set은 동일한 자동 복구 기능이다."],"rubric":[{"label":"개념 정확성","max":4},{"label":"원리·인과관계","max":3},{"label":"비교·적용","max":2},{"label":"논리적 구성","max":1}]},{"ex":[4],"title":"네트워크 연결 설명","text":"주소 공간·서브넷·피어링·VPN·ExpressRoute·DNS를 설명하고 경로와 접근 허용을 구분하세요.","answer":"VNet 주소 공간을 서브넷으로 나누고 자원 간 통신 경로를 구성한다. 피어링은 VNet 사이, VPN·ExpressRoute는 온프레미스 연결 요구에 연결한다. DNS는 이름 해석이다. 경로가 존재하는지와 접근이 허용되는지는 다른 질문이다. 사설 주소·Private Endpoint·공개 노출을 같은 개념으로 설명하거나 VM 자체 공인 IP를 모든 인터넷 접속의 필수로 단정해서는 안 된다.","points":["주소 공간과 서브넷","VNet·온프레미스 연결","DNS 이름 해석","경로·허용·주소 구분"],"sourceIds":["DC-run-C06-2-ex4"],"locator":"직접 확인한 DataCamp 수업 / ex=4","claimId":"C06-2-expanded-8","contentType":"자체 작성 서술형 예상문제","id":"Q-C06-2-2","modelAnswer":"VNet 주소 공간을 서브넷으로 나누고 자원 간 통신 경로를 구성한다. 피어링은 VNet 사이, VPN·ExpressRoute는 온프레미스 연결 요구에 연결한다. DNS는 이름 해석이다. 경로가 존재하는지와 접근이 허용되는지는 다른 질문이다. 사설 주소·Private Endpoint·공개 노출을 같은 개념으로 설명하거나 VM 자체 공인 IP를 모든 인터넷 접속의 필수로 단정해서는 안 된다.","version":"2026-10-16-expanded-v1","type":"자체 작성 서술형 예상문제","sourceLocator":"직접 확인한 DataCamp 수업 / ex=4","conceptIds":["C06-2-concept-2"],"objective":"VNet·서브넷·피어링·연결·DNS를 연결한다.","expectedLength":"핵심 논점 중심 5~7문장","acceptedAlternatives":"동일한 개념·인과관계와 요구를 충족하는 대안 표현을 인정합니다. 서비스 이름만 같은 답은 충분하지 않습니다.","commonMistakes":["VM 인터넷 연결에는 반드시 자체 공인 IP가 필요하며 사설 IP는 Private Endpoint다."],"rubric":[{"label":"개념 정확성","max":4},{"label":"원리·인과관계","max":3},{"label":"비교·적용","max":2},{"label":"논리적 구성","max":1}]},{"ex":[1,13],"title":"앱을 역할별로 배치하기","text":"웹·API·백그라운드 작업과 VM·App Service·Functions·컨테이너 서비스를 연결해 선택 기준을 설명하세요.","answer":"먼저 웹·API·백그라운드 작업과 데이터 역할을 나눈다. OS 제어가 필요하면 VM, 웹·API 플랫폼을 이용하면 App Service, 트리거 실행이면 Functions를 비교한다. 컨테이너에서는 Registry의 이미지 저장, ACI의 실행, AKS의 조율을 구분한다. API는 내부 구현과 통신 규약을 분리하는 역할이다. 모든 이전이 VM부터 시작하거나 모든 앱이 VNet에 직접 배치되어야 한다고 일반화할 수는 없다.","points":["앱·데이터 역할 분리","VM·플랫폼·함수 기준","이미지·실행·조율 구분","API 의미와 일반화 한계"],"sourceIds":["DC-run-C06-2-ex1","DC-run-C06-2-ex13"],"locator":"직접 확인한 DataCamp 수업 / ex=1, 13","claimId":"C06-2-expanded-9","contentType":"자체 작성 서술형 예상문제","id":"Q-C06-2-3","modelAnswer":"먼저 웹·API·백그라운드 작업과 데이터 역할을 나눈다. OS 제어가 필요하면 VM, 웹·API 플랫폼을 이용하면 App Service, 트리거 실행이면 Functions를 비교한다. 컨테이너에서는 Registry의 이미지 저장, ACI의 실행, AKS의 조율을 구분한다. API는 내부 구현과 통신 규약을 분리하는 역할이다. 모든 이전이 VM부터 시작하거나 모든 앱이 VNet에 직접 배치되어야 한다고 일반화할 수는 없다.","version":"2026-10-16-expanded-v1","type":"자체 작성 서술형 예상문제","sourceLocator":"직접 확인한 DataCamp 수업 / ex=1, 13","conceptIds":["C06-2-concept-1","C06-2-concept-6"],"objective":"확장·장애 분산과 앱 실행 선택을 구분한다.","expectedLength":"핵심 논점 중심 5~7문장","acceptedAlternatives":"동일한 개념·인과관계와 요구를 충족하는 대안 표현을 인정합니다. 서비스 이름만 같은 답은 충분하지 않습니다.","commonMistakes":[],"rubric":[{"label":"개념 정확성","max":4},{"label":"원리·인과관계","max":3},{"label":"비교·적용","max":2},{"label":"논리적 구성","max":1}]}]},"C06-3":{"concepts":[{"id":"C06-3-concept-1","term":"클라우드 ID와 SSO","english":"AD · Microsoft Entra ID","ex":[1],"text":"온프레미스 AD의 사용자·컴퓨터·그룹과 Entra ID의 인증·앱·기기·외부 협업·하이브리드 동기화를 구분한다. SSO는 인증 흐름을 재사용하는 방식이지 모든 앱의 비밀번호를 똑같이 저장한다는 뜻이 아니다. Entra ID를 AD와 프로토콜까지 동일한 단순 온라인 복제판으로 설명하지 않는다.","sourceIds":["DC-run-C06-3-ex1"],"locator":"직접 확인한 DataCamp 수업 / ex=1","claimId":"C06-3-expanded-1","contentType":"DataCamp 강의 확인 내용"},{"id":"C06-3-concept-2","term":"인증의 여러 선택","english":"MFA · Passwordless","ex":[6],"text":"MFA는 서로 다른 요소를 결합한다. 비밀번호와 보안 질문처럼 같은 지식 유형을 둘 쓴다고 자동으로 다른 요소가 되지는 않는다. 패스워드리스는 기기·키 기반 확인 등을 이용하며 Hello·Authenticator·FIDO2가 수업 예다.","sourceIds":["DC-run-C06-3-ex6"],"locator":"직접 확인한 DataCamp 수업 / ex=6","claimId":"C06-3-expanded-2","contentType":"DataCamp 강의 확인 내용"},{"id":"C06-3-concept-3","term":"조건부 액세스","english":"Conditional Access","ex":[6],"text":"사용자·위치·기기 같은 신호를 정책 조건과 비교해 허용·차단·추가 검증을 결정한다. MFA는 인증 요소, 조건부 액세스는 언제 어떤 접근 조건을 적용할지의 판단이다. 네트워크 위치·기기 준수·앱 조건은 서로 다른 기준이다.","sourceIds":["DC-run-C06-3-ex6"],"locator":"직접 확인한 DataCamp 수업 / ex=6","claimId":"C06-3-expanded-3","contentType":"DataCamp 강의 확인 내용"},{"id":"C06-3-concept-4","term":"사용자·그룹과 역할","english":"Users · Groups · Directory roles","ex":[10,11],"text":"사용자·그룹은 ID를 관리하고 역할을 배정할 주체와 연결된다. 디렉터리 역할은 ID·디렉터리 관리 작업의 권한이다. 사용자 생성·구성원 배정의 시연과 실제 권한 확대를 구분하며 여기서는 새 자격을 만들 필요가 없다.","sourceIds":["DC-run-C06-3-ex10","DC-run-C06-3-ex11"],"locator":"직접 확인한 DataCamp 수업 / ex=10, 11","claimId":"C06-3-expanded-4","contentType":"DataCamp 강의 확인 내용"},{"id":"C06-3-concept-5","term":"리소스 권한의 세 요소","english":"Azure RBAC","ex":[11,15],"text":"Azure RBAC 역할 할당은 주체·역할·범위의 조합이다. Reader는 관리 정보 조회, Contributor는 자원 관리, Owner는 자원 관리와 권한 부여를 맡는다. Blob 데이터 읽기는 Storage Blob Data Reader처럼 데이터 역할을 구분한다. 구독 Contributor에 하위 Reader를 추가해도 기존 권한은 유지되므로 원래 할당을 조정해야 한다.","sourceIds":["DC-run-C06-3-ex11","DC-run-C06-3-ex15"],"locator":"직접 확인한 DataCamp 수업 / ex=11, 15","claimId":"C06-3-expanded-5","contentType":"DataCamp 강의 확인 내용"},{"id":"C06-3-concept-6","term":"보안 목표와 전략","english":"CIA · Zero Trust · Defense in depth · Defender","ex":[17],"text":"기밀성·무결성·가용성은 보호 목표다. Zero Trust는 명시 검증·최소 권한·침해 가정, 심층 방어는 여러 보호 계층으로 실패 영향을 줄이는 전략이다. Defender for Cloud는 지속 평가→강화→탐지·대응에 연결한다. 여러 계층의 존재가 침해 완전 방지를 보장하지는 않는다.","sourceIds":["DC-run-C06-3-ex17"],"locator":"직접 확인한 DataCamp 수업 / ex=17","claimId":"C06-3-expanded-6","contentType":"DataCamp 강의 확인 내용"}],"comparisons":[{"title":"접근 제어의 다른 질문들","ex":[1,6,11,15,17],"headers":["개념","주 질문","예","혼동 방지"],"rows":[["인증","누구인가?","MFA·패스워드리스","작업 허용과 다름"],["조건부 액세스","어떤 조건에 허용할까?","기기·위치·사용자 신호","MFA와 같은 뜻 아님"],["디렉터리 역할","ID를 누가 관리하나?","디렉터리 관리 권한","리소스 역할과 다름"],["Azure RBAC","무엇을 어디에서 하나?","주체·역할·범위","관리와 데이터 작업 구분"],["Zero Trust / 심층 방어","어떤 전략으로 줄일까?","검증·최소 권한 / 다층 보호","완전 차단 보장 아님"]],"sourceIds":["DC-run-C06-3-ex1","DC-run-C06-3-ex6","DC-run-C06-3-ex11","DC-run-C06-3-ex15","DC-run-C06-3-ex17"],"locator":"직접 확인한 DataCamp 수업 / ex=1, 6, 11, 15, 17","claimId":"C06-3-expanded-12","contentType":"학습용 비교 재구성"}],"questions":[{"ex":[1,6],"title":"ID와 인증 조건","text":"Entra ID·SSO·MFA·패스워드리스·조건부 액세스를 서로 다른 역할로 설명하세요.","answer":"Entra ID는 클라우드 ID·인증과 앱·기기 관리 등에 연결하고 SSO는 인증 흐름 재사용이다. MFA는 서로 다른 요소 결합, 패스워드리스는 비밀번호 대신 기기·키 등을 사용하는 확인 방식이다. 조건부 액세스는 사용자·위치·기기 신호로 허용·차단·추가 검증을 판단한다. 비밀번호와 보안 질문은 모두 지식 유형일 수 있다. 인증 조건과 자원의 작업 권한은 별도 문제다.","points":["Entra ID와 SSO","MFA 요소와 패스워드리스","조건부 판단 흐름","인증과 권한 구분"],"sourceIds":["DC-run-C06-3-ex1","DC-run-C06-3-ex6"],"locator":"직접 확인한 DataCamp 수업 / ex=1, 6","claimId":"C06-3-expanded-7","contentType":"자체 작성 서술형 예상문제","id":"Q-C06-3-1","modelAnswer":"Entra ID는 클라우드 ID·인증과 앱·기기 관리 등에 연결하고 SSO는 인증 흐름 재사용이다. MFA는 서로 다른 요소 결합, 패스워드리스는 비밀번호 대신 기기·키 등을 사용하는 확인 방식이다. 조건부 액세스는 사용자·위치·기기 신호로 허용·차단·추가 검증을 판단한다. 비밀번호와 보안 질문은 모두 지식 유형일 수 있다. 인증 조건과 자원의 작업 권한은 별도 문제다.","version":"2026-10-16-expanded-v1","type":"자체 작성 서술형 예상문제","sourceLocator":"직접 확인한 DataCamp 수업 / ex=1, 6","conceptIds":["C06-3-concept-1","C06-3-concept-2","C06-3-concept-3"],"objective":"인증·MFA·패스워드리스·조건부 액세스를 구분한다.","expectedLength":"핵심 논점 중심 5~7문장","acceptedAlternatives":"동일한 개념·인과관계와 요구를 충족하는 대안 표현을 인정합니다. 서비스 이름만 같은 답은 충분하지 않습니다.","commonMistakes":["비밀번호와 보안 질문은 반드시 MFA이며 MFA가 모든 권한을 정한다."],"rubric":[{"label":"개념 정확성","max":4},{"label":"원리·인과관계","max":3},{"label":"비교·적용","max":2},{"label":"논리적 구성","max":1}]},{"ex":[11,15],"title":"범위를 가진 역할 배정","text":"디렉터리 역할과 Azure RBAC를 비교하고 주체·역할·범위·상속·관리/데이터 작업을 설명하세요.","answer":"Entra 역할은 디렉터리 관리, Azure RBAC는 Azure 자원 작업 권한에 초점을 둔다. 역할을 주체와 범위에 할당하면 하위로 상속된다. Reader는 관리 정보 조회, Contributor는 자원 관리, Owner는 권한 부여까지 포함한다. 관리 정보 조회와 Blob 데이터 읽기는 별도다. 구독 Contributor 아래에 Reader를 추가해도 권한은 줄지 않으므로 상위 할당을 제거·재설계하고 필요한 범위에 최소 권한으로 재할당한다.","points":["디렉터리와 자원 권한","주체·역할·범위","상속과 최소 범위","관리·데이터 작업 구분"],"sourceIds":["DC-run-C06-3-ex11","DC-run-C06-3-ex15"],"locator":"직접 확인한 DataCamp 수업 / ex=11, 15","claimId":"C06-3-expanded-8","contentType":"자체 작성 서술형 예상문제","id":"Q-C06-3-2","modelAnswer":"디렉터리 역할은 ID·디렉터리 관리, Azure RBAC는 Azure 리소스 작업 권한에 연결한다. RBAC 역할 배정은 주체에게 특정 범위에서 작업 집합을 부여하는 것이다. 상위 범위의 허용은 하위로 상속되므로 최소 범위를 검토한다. 관리 역할과 Blob 데이터 작업 역할은 구분해야 한다. 상위 허용이 하위 배정만으로 간단히 제거된다고 가정하지 않고 실제 유효 권한과 공식 보충 근거를 확인한다.","version":"2026-10-16-expanded-v1","type":"자체 작성 서술형 예상문제","sourceLocator":"직접 확인한 DataCamp 수업 / ex=11, 15","conceptIds":["C06-3-concept-4","C06-3-concept-5"],"objective":"디렉터리 역할과 RBAC의 주체·역할·범위를 설명한다.","expectedLength":"핵심 논점 중심 5~7문장","acceptedAlternatives":"동일한 개념·인과관계와 요구를 충족하는 대안 표현을 인정합니다. 서비스 이름만 같은 답은 충분하지 않습니다.","commonMistakes":["Contributor는 모든 Blob 데이터를 읽고 하위에서 상위 허용을 쉽게 끊을 수 있다."],"rubric":[{"label":"개념 정확성","max":4},{"label":"원리·인과관계","max":3},{"label":"비교·적용","max":2},{"label":"논리적 구성","max":1}]},{"ex":[17],"title":"보안 전략 연결","text":"CIA·공동 책임·Zero Trust·심층 방어·Defender for Cloud를 연결해 설명하세요.","answer":"CIA는 기밀성·무결성·가용성의 보호 목표다. 공동 책임에 따라 고객에게 남는 ID·데이터·구성 보호를 확인한다. Zero Trust는 명시 검증·최소 권한·침해 가정으로 접근한다. 심층 방어는 여러 계층으로 한 통제 실패의 영향을 줄이고 Defender for Cloud는 평가·강화·탐지와 대응에 연결한다. 이 전략은 지속 개선이 필요하며 침해 완전 방지를 보장하지 않는다.","points":["CIA 목표","고객의 남는 책임","Zero Trust 세 원칙","다층 보호·평가와 한계"],"sourceIds":["DC-run-C06-3-ex17"],"locator":"직접 확인한 DataCamp 수업 / ex=17","claimId":"C06-3-expanded-9","contentType":"자체 작성 서술형 예상문제","id":"Q-C06-3-3","modelAnswer":"CIA는 기밀성·무결성·가용성의 보호 목표다. 공동 책임에 따라 고객에게 남는 ID·데이터·구성 보호를 확인한다. Zero Trust는 명시 검증·최소 권한·침해 가정으로 접근한다. 심층 방어는 여러 계층으로 한 통제 실패의 영향을 줄이고 Defender for Cloud는 평가·강화·탐지와 대응에 연결한다. 이 전략은 지속 개선이 필요하며 침해 완전 방지를 보장하지 않는다.","version":"2026-10-16-expanded-v1","type":"자체 작성 서술형 예상문제","sourceLocator":"직접 확인한 DataCamp 수업 / ex=17","conceptIds":["C06-3-concept-6"],"objective":"Zero Trust와 심층 방어를 공동 책임에 연결한다.","expectedLength":"핵심 논점 중심 5~7문장","acceptedAlternatives":"동일한 개념·인과관계와 요구를 충족하는 대안 표현을 인정합니다. 서비스 이름만 같은 답은 충분하지 않습니다.","commonMistakes":[],"rubric":[{"label":"개념 정확성","max":4},{"label":"원리·인과관계","max":3},{"label":"비교·적용","max":2},{"label":"논리적 구성","max":1}]}]},"C07-2":{"concepts":[{"id":"C07-2-concept-1","term":"비용을 바꾸는 요인","english":"Usage · Subscription · Configuration · Location","ex":[1],"text":"사용량, 구독 조건, 자원 유형·설정, 지역·전송이 비용에 영향을 준다. VM 실행 요금 외에도 연결된 저장·전송 등 조건을 함께 비교한다. 리소스를 만들기만 하면 모든 요금이 없다는 식의 일반화는 피한다.","sourceIds":["DC-run-C07-2-ex1"],"locator":"직접 확인한 DataCamp 수업 / ex=1","claimId":"C07-2-expanded-1","contentType":"DataCamp 강의 확인 내용"},{"id":"C07-2-concept-2","term":"세 비용 도구","english":"Pricing Calculator · TCO · Cost Management","ex":[5,17],"text":"계산기는 새 제품·설정의 견적, TCO는 온프레미스와 클라우드의 운영·숨은 비용 포함 비교다. Cost Management는 실제 지출·분석·예산·알림의 허브다. 과거 기반 예측과 견적의 가정은 실제 청구나 절감 보장과 다르다.","sourceIds":["DC-run-C07-2-ex5","DC-run-C07-2-ex17"],"locator":"직접 확인한 DataCamp 수업 / ex=5, 17","claimId":"C07-2-expanded-2","contentType":"DataCamp 강의 확인 내용"},{"id":"C07-2-concept-3","term":"비용을 보는 차원","english":"Cost Analysis · Tags · Forecast","ex":[5],"text":"기간·태그 등 기준으로 비용을 나누어 어떤 자원이 지출을 만드는지 찾는다. 과거 사용을 기반으로 추세·예측을 검토하고 보고·내보내기로 공유한다. 예측이 맞으려면 사용 조건이 어떻게 달라지는지도 확인해야 한다.","sourceIds":["DC-run-C07-2-ex5"],"locator":"직접 확인한 DataCamp 수업 / ex=5","claimId":"C07-2-expanded-3","contentType":"DataCamp 강의 확인 내용"},{"id":"C07-2-concept-4","term":"제공업체 문서와 데이터 자산","english":"Service Trust Portal · Purview","ex":[9],"text":"Service Trust Portal은 Microsoft의 감사·보호 자료를 확인한다. Purview Data Map은 원본 스캔과 메타데이터 수집, Catalog는 자산 검색·의미·담당자 파악에 쓰인다. 계보는 데이터의 출처와 변환 경로를 추적한다. Compliance Manager는 평가·담당자·증거·개선 활동을 관리하며 점수는 준수 인증과 다르다.","sourceIds":["DC-run-C07-2-ex9"],"locator":"직접 확인한 DataCamp 수업 / ex=9","claimId":"C07-2-expanded-4","contentType":"DataCamp 강의 확인 내용"},{"id":"C07-2-concept-5","term":"리소스 규칙과 묶음","english":"Azure Policy · Initiative","ex":[13],"text":"Policy는 규칙의 적용 범위와 효과를 통해 자원 기준·준수 상태를 관리한다. Initiative는 같은 목적의 여러 정책 묶음이다. 평가·거부·수정은 같은 동작이 아니며 자동 수정은 효과와 별도 수정 작업 조건을 확인해야 한다.","sourceIds":["DC-run-C07-2-ex13"],"locator":"직접 확인한 DataCamp 수업 / ex=13","claimId":"C07-2-expanded-5","contentType":"DataCamp 강의 확인 내용"},{"id":"C07-2-concept-6","term":"수업 시점의 배포 표준화","english":"Azure Blueprints — course context","ex":[13],"text":"Blueprints는 역할·정책·리소스 그룹·ARM 템플릿을 묶어 환경을 표준화하는 교재 개념이다. 대체 구성에서 Template Specs는 템플릿을 저장·버전 관리·공유하고 Deployment Stacks는 배포한 자원 묶음의 수명주기를 관리한다. Policy는 기준 평가, 템플릿은 구성 정의, 스택은 자원 묶음 관리로 구분한다.","sourceIds":["DC-run-C07-2-ex13"],"locator":"직접 확인한 DataCamp 수업 / ex=13","claimId":"C07-2-expanded-6","contentType":"DataCamp 강의 확인 내용"}],"comparisons":[{"title":"비슷한 도구라도 결과가 다르다","ex":[5,9,13],"headers":["도구","입력·대상","얻는 결과","한계"],"rows":[["Pricing Calculator","미래 구성 가정","예상 요금","청구 보장 아님"],["TCO","기존·전환 후 전체 비용","전환 비교","실제 절감 보장 아님"],["Cost Management","실제 사용·지출","분석·예산·예측","자동 중단 보장 아님"],["Trust Portal / Purview","제공업체 문서 / 데이터 자산","문서 / 목록·계보·평가","준수 인증 자동 아님"],["Policy / Initiative","규칙 / 규칙 묶음","기준 관리","모든 위반 자동 수정 아님"]],"sourceIds":["DC-run-C07-2-ex5","DC-run-C07-2-ex9","DC-run-C07-2-ex13"],"locator":"직접 확인한 DataCamp 수업 / ex=5, 9, 13","claimId":"C07-2-expanded-12","contentType":"학습용 비교 재구성"}],"questions":[{"ex":[1,5,17],"title":"비용 계획과 실제 분석","text":"비용 요인을 설명하고 계산기·TCO·Cost Management·예측의 차이를 쓰세요.","answer":"사용량·구독 조건·자원 설정·지역과 전송이 비용에 영향을 준다. 가격 계산기는 새 구성의 가정별 견적, TCO는 기존 환경과 전환 후 총비용 비교다. Cost Management는 실제 지출·예산·분석을 다룬다. 과거 기반 예측은 앞으로의 경향을 보는 결과이며 사용 조건 변화에 영향을 받는다. 따라서 견적·예측을 실제 청구나 절감 보장으로 볼 수 없다.","points":["네 비용 요인","견적과 총비용","실제 분석·예측","가정과 보장 한계"],"sourceIds":["DC-run-C07-2-ex1","DC-run-C07-2-ex5","DC-run-C07-2-ex17"],"locator":"직접 확인한 DataCamp 수업 / ex=1, 5, 17","claimId":"C07-2-expanded-7","contentType":"자체 작성 서술형 예상문제","id":"Q-C07-2-1","modelAnswer":"사용량·구독 조건·자원 설정·지역과 전송이 비용에 영향을 준다. 가격 계산기는 새 구성의 가정별 견적, TCO는 기존 환경과 전환 후 총비용 비교다. Cost Management는 실제 지출·예산·분석을 다룬다. 과거 기반 예측은 앞으로의 경향을 보는 결과이며 사용 조건 변화에 영향을 받는다. 따라서 견적·예측을 실제 청구나 절감 보장으로 볼 수 없다.","version":"2026-10-16-expanded-v1","type":"자체 작성 서술형 예상문제","sourceLocator":"직접 확인한 DataCamp 수업 / ex=1, 5, 17","conceptIds":["C07-2-concept-1","C07-2-concept-2","C07-2-concept-3"],"objective":"비용 요인과 견적·총비용·실제 분석을 연결한다.","expectedLength":"핵심 논점 중심 5~7문장","acceptedAlternatives":"동일한 개념·인과관계와 요구를 충족하는 대안 표현을 인정합니다. 서비스 이름만 같은 답은 충분하지 않습니다.","commonMistakes":["TCO가 실제 청구이고 Compliance Manager 점수는 법적 인증이다."],"rubric":[{"label":"개념 정확성","max":4},{"label":"원리·인과관계","max":3},{"label":"비교·적용","max":2},{"label":"논리적 구성","max":1}]},{"ex":[9],"title":"준수와 데이터 거버넌스","text":"Service Trust Portal·Purview Catalog·Data Map·Compliance Manager를 역할로 비교하세요.","answer":"Service Trust Portal은 제공업체의 감사·보호 근거를 확인한다. Data Map은 데이터 원본을 스캔해 메타데이터를 모으고 Catalog는 자산 검색과 의미·담당자 이해를 돕는다. 계보는 데이터의 출처와 변환 경로를 보여 준다. Compliance Manager는 평가와 담당자·증거·개선 상태를 관리한다. 문서 확인·자산 발견·계보·준수 개선은 서로 다른 기능이다.","points":["제공업체 문서","자산·메타데이터 목록","흐름·계보와 평가","준수 보장과 구분"],"sourceIds":["DC-run-C07-2-ex9"],"locator":"직접 확인한 DataCamp 수업 / ex=9","claimId":"C07-2-expanded-8","contentType":"자체 작성 서술형 예상문제","id":"Q-C07-2-2","modelAnswer":"Service Trust Portal은 Microsoft의 보안·개인정보·준수 문서를 확인하는 경로다. 수업의 Purview Catalog는 데이터 자산과 메타데이터 목록, Data Map은 데이터 흐름·계보에 연결한다. Compliance Manager는 평가와 점수·개선 권고를 다룬다. 문서 확인·자산 파악·계보·평가는 서로 다른 목적이다. 도구 점수가 법적 인증이나 모든 요구 충족을 자동 보장하지는 않는다.","version":"2026-10-16-expanded-v1","type":"자체 작성 서술형 예상문제","sourceLocator":"직접 확인한 DataCamp 수업 / ex=9","conceptIds":["C07-2-concept-4"],"objective":"보안·준수 문서와 데이터 거버넌스 도구를 구분한다.","expectedLength":"핵심 논점 중심 5~7문장","acceptedAlternatives":"동일한 개념·인과관계와 요구를 충족하는 대안 표현을 인정합니다. 서비스 이름만 같은 답은 충분하지 않습니다.","commonMistakes":["TCO가 실제 청구이고 Compliance Manager 점수는 법적 인증이다."],"rubric":[{"label":"개념 정확성","max":4},{"label":"원리·인과관계","max":3},{"label":"비교·적용","max":2},{"label":"논리적 구성","max":1}]},{"ex":[13],"title":"정책과 표준 배포","text":"Policy·Initiative와 수업의 Blueprints를 구분하고 자동 수정과 현재 제품 사용의 한계를 설명하세요.","answer":"Policy는 자원 기준과 효과를 정의하고 Initiative는 관련 정책을 묶는다. Blueprints는 역할·정책·그룹·템플릿을 묶는 표준화 개념이다. 대체 방식의 Template Specs는 템플릿 저장·버전·공유, Deployment Stacks는 배포 자원 묶음의 수명주기 관리를 맡는다. 정책 평가·배포 정의·자원 묶음 관리는 다른 역할이며 감사·거부·수정 효과도 구분한다.","points":["정책과 정책 묶음","범위·효과·수정 조건","배포 아티팩트 표준화","수업 시점과 현재 상태 구분"],"sourceIds":["DC-run-C07-2-ex13"],"locator":"직접 확인한 DataCamp 수업 / ex=13","claimId":"C07-2-expanded-9","contentType":"자체 작성 서술형 예상문제","id":"Q-C07-2-3","modelAnswer":"Policy는 자원 규칙과 준수 상태를 관리하고 Initiative는 공통 목적의 정책 묶음이다. 적용 범위와 효과를 확인하며 위반 평가와 실제 수정은 구분한다. 수업의 Blueprints는 역할·정책·그룹·ARM 템플릿 아티팩트를 묶어 환경을 표준화하는 예다. 이는 개별 정책 기준과 배포 묶음이라는 목적 차이를 보여준다. 자동 수정 조건과 제품의 현재 제공 상태는 별도 확인이 필요하다.","version":"2026-10-16-expanded-v1","type":"자체 작성 서술형 예상문제","sourceLocator":"직접 확인한 DataCamp 수업 / ex=13","conceptIds":["C07-2-concept-5","C07-2-concept-6"],"objective":"Policy·Initiative와 수업의 Blueprints를 목적별로 설명한다.","expectedLength":"핵심 논점 중심 5~7문장","acceptedAlternatives":"동일한 개념·인과관계와 요구를 충족하는 대안 표현을 인정합니다. 서비스 이름만 같은 답은 충분하지 않습니다.","commonMistakes":["Policy는 위반을 발견하면 무조건 자동 수정하며 Initiative는 별도 권한 체계다."],"rubric":[{"label":"개념 정확성","max":4},{"label":"원리·인과관계","max":3},{"label":"비교·적용","max":2},{"label":"논리적 구성","max":1}]}]},"C07-3":{"concepts":[{"id":"C07-3-concept-1","term":"관리 인터페이스","english":"Portal · PowerShell · Azure CLI · Arc · Mobile","ex":[1],"text":"Portal은 웹 GUI, PowerShell·Azure CLI는 명령·스크립트 자동화에 연결한다. Arc는 외부·온프레미스 자원을 Azure 관리 범위로 연결하고 모바일 앱은 이동 중 상태 관리에 쓰인다. CLI를 특정 셸 하나와 동일시하지 않고 인터페이스 선택을 업무·반복성 요구에 연결한다.","sourceIds":["DC-run-C07-3-ex1"],"locator":"직접 확인한 DataCamp 수업 / ex=1","claimId":"C07-3-expanded-1","contentType":"DataCamp 강의 확인 내용"},{"id":"C07-3-concept-2","term":"관리 요청과 배포 정의","english":"ARM · Resource providers · ARM templates · Bicep","ex":[5],"text":"리소스 그룹은 관련 자원을 수명주기로 묶고 ARM은 관리 요청을 조정한다. Microsoft.Compute 같은 공급자가 유형별 작업을 수행한다. 템플릿·Bicep은 재사용·버전 관리 가능한 배포 정의다. 자동 확장 설정을 배포하는 것과 템플릿 자체가 실시간 부하를 관찰하는 것은 다르다.","sourceIds":["DC-run-C07-3-ex5"],"locator":"직접 확인한 DataCamp 수업 / ex=5","claimId":"C07-3-expanded-2","contentType":"DataCamp 강의 확인 내용"},{"id":"C07-3-concept-3","term":"관측 데이터","english":"Metrics · Logs","ex":[9],"text":"메트릭은 성능 수치, 로그는 작업·이벤트의 상세 기록이다. 수집→분석·시각화→경고·대응으로 이어진다. 수집만으로 문제 해결이 끝나는 것은 아니며 어떤 신호가 어떤 상태를 뜻하는지 해석해야 한다.","sourceIds":["DC-run-C07-3-ex9"],"locator":"직접 확인한 DataCamp 수업 / ex=9","claimId":"C07-3-expanded-3","contentType":"DataCamp 강의 확인 내용"},{"id":"C07-3-concept-4","term":"앱과 로그 분석","english":"Application Insights · Log Analytics","ex":[13],"text":"Application Insights는 앱 성능·가용성·사용 진단에 연결한다. Log Analytics는 로그 쿼리와 더 넓은 환경 분석에 연결한다. 앱 내부 문제와 환경의 여러 기록을 구분해 필요한 증거를 조사한다.","sourceIds":["DC-run-C07-3-ex13"],"locator":"직접 확인한 DataCamp 수업 / ex=13","claimId":"C07-3-expanded-4","contentType":"DataCamp 강의 확인 내용"},{"id":"C07-3-concept-5","term":"경고의 세 구성","english":"Alert rule · Action group · Alert processing rule","ex":[18],"text":"Alert rule은 범위·신호·집계·비교·임계값을 정한다. Action group은 통보·대응, Alert processing rule은 유지보수 중 억제 등을 맡는다. 수업 예시는 최근 5분 평균 가용 메모리 2GiB 미만이다. 가용량은 낮을수록 부족하므로 미만, 사용량은 높아지는 초과 조건을 구분한다.","sourceIds":["DC-run-C07-3-ex18"],"locator":"직접 확인한 DataCamp 수업 / ex=18","claimId":"C07-3-expanded-5","contentType":"DataCamp 강의 확인 내용"},{"id":"C07-3-concept-6","term":"서비스 상태와 개선 권고","english":"Service Health · Advisor","ex":[13],"text":"Service Health는 구독 관련 장애·유지보수 정보, Advisor는 비용·보안·성능·안정성·운영 우수성 권고다. 내 앱의 관측 결과와 제공업체 서비스 상태를 함께 비교할 수 있다. 권고를 얻은 사실을 자동 적용 완료로 표시하지 않는다.","sourceIds":["DC-run-C07-3-ex13"],"locator":"직접 확인한 DataCamp 수업 / ex=13","claimId":"C07-3-expanded-6","contentType":"DataCamp 강의 확인 내용"}],"comparisons":[{"title":"경고·상태·권고를 혼동하지 않기","ex":[9,13,18],"headers":["구성","목적","결과","구분할 기능"],"rows":[["메트릭 / 로그","수치 / 상세 기록","관측 데이터","조치 자체 아님"],["App Insights / Log Analytics","앱 진단 / 로그 분석","분석 근거","서비스 전체 장애 정보와 다름"],["경고 규칙","조건 판단","경고 발생","메일 발송 설정과 구분"],["작업 그룹 / 처리 규칙","통보·대응 / 억제 관리","연결된 작업 / 경고 관리","신호 정의와 다름"],["Service Health / Advisor","서비스 상태 / 개선점","장애·유지보수 / 권고","자동 수정 아님"]],"sourceIds":["DC-run-C07-3-ex9","DC-run-C07-3-ex13","DC-run-C07-3-ex18"],"locator":"직접 확인한 DataCamp 수업 / ex=9, 13, 18","claimId":"C07-3-expanded-12","contentType":"학습용 비교 재구성"}],"questions":[{"ex":[1,5],"title":"관리 도구와 ARM 구조","text":"Portal·명령 도구·Arc와 ARM·공급자·템플릿의 역할을 구분하세요.","answer":"Portal은 GUI, PowerShell·Azure CLI는 명령·스크립트 자동화, Arc는 외부 자원을 관리 범위에 연결하는 역할이다. ARM은 관리 요청을 조정하고 자원 공급자는 유형별 작업을 수행한다. 리소스 그룹은 관련 자원을 수명주기로 묶는다. ARM 템플릿·Bicep은 재사용·버전 관리하는 배포 정의다. 인터페이스·관리 처리·구성 정의는 다른 층이며 템플릿이 실시간 관측 자체를 수행하는 것은 아니다.","points":["인터페이스 선택","ARM과 공급자","그룹과 배포 정의","계층과 관측 구분"],"sourceIds":["DC-run-C07-3-ex1","DC-run-C07-3-ex5"],"locator":"직접 확인한 DataCamp 수업 / ex=1, 5","claimId":"C07-3-expanded-7","contentType":"자체 작성 서술형 예상문제","id":"Q-C07-3-1","modelAnswer":"Portal은 GUI, PowerShell·Azure CLI는 명령·스크립트 자동화, Arc는 외부 자원을 관리 범위에 연결하는 역할이다. ARM은 관리 요청을 조정하고 자원 공급자는 유형별 작업을 수행한다. 리소스 그룹은 관련 자원을 수명주기로 묶는다. ARM 템플릿·Bicep은 재사용·버전 관리하는 배포 정의다. 인터페이스·관리 처리·구성 정의는 다른 층이며 템플릿이 실시간 관측 자체를 수행하는 것은 아니다.","version":"2026-10-16-expanded-v1","type":"자체 작성 서술형 예상문제","sourceLocator":"직접 확인한 DataCamp 수업 / ex=1, 5","conceptIds":["C07-3-concept-1","C07-3-concept-2"],"objective":"GUI·명령·외부 자원 관리의 인터페이스를 비교한다.","expectedLength":"핵심 논점 중심 5~7문장","acceptedAlternatives":"동일한 개념·인과관계와 요구를 충족하는 대안 표현을 인정합니다. 서비스 이름만 같은 답은 충분하지 않습니다.","commonMistakes":["Bicep 템플릿이 부하를 직접 관찰하고 Advisor가 모든 권고를 적용한다."],"rubric":[{"label":"개념 정확성","max":4},{"label":"원리·인과관계","max":3},{"label":"비교·적용","max":2},{"label":"논리적 구성","max":1}]},{"ex":[9,13],"title":"관측·상태·권고의 차이","text":"메트릭·로그·Application Insights·Log Analytics·Service Health·Advisor를 구분하세요.","answer":"메트릭은 수치, 로그는 상세 이벤트·작업 기록이다. Application Insights는 앱 성능·가용성·사용 진단, Log Analytics는 로그 쿼리와 환경 분석에 연결한다. Service Health는 구독 관련 장애·유지보수 정보다. Advisor는 비용·보안·성능·안정성·운영 우수성의 권고를 제공한다. 이 근거들을 비교해 원인과 조치를 판단하며 권고가 자동 적용되었다고 볼 수는 없다.","points":["수치와 상세 기록","앱 진단과 로그 분석","서비스 상태와 개선 권고","근거 비교와 조치 구분"],"sourceIds":["DC-run-C07-3-ex9","DC-run-C07-3-ex13"],"locator":"직접 확인한 DataCamp 수업 / ex=9, 13","claimId":"C07-3-expanded-8","contentType":"자체 작성 서술형 예상문제","id":"Q-C07-3-2","modelAnswer":"메트릭은 수치, 로그는 상세 이벤트·작업 기록이다. Application Insights는 앱 성능·가용성·사용 진단, Log Analytics는 로그 쿼리와 환경 분석에 연결한다. Service Health는 구독 관련 장애·유지보수 정보다. Advisor는 비용·보안·성능·안정성·운영 우수성의 권고를 제공한다. 이 근거들을 비교해 원인과 조치를 판단하며 권고가 자동 적용되었다고 볼 수는 없다.","version":"2026-10-16-expanded-v1","type":"자체 작성 서술형 예상문제","sourceLocator":"직접 확인한 DataCamp 수업 / ex=9, 13","conceptIds":["C07-3-concept-3","C07-3-concept-4","C07-3-concept-6"],"objective":"ARM·공급자·배포 정의의 관계를 설명한다.","expectedLength":"핵심 논점 중심 5~7문장","acceptedAlternatives":"동일한 개념·인과관계와 요구를 충족하는 대안 표현을 인정합니다. 서비스 이름만 같은 답은 충분하지 않습니다.","commonMistakes":["Bicep 템플릿이 부하를 직접 관찰하고 Advisor가 모든 권고를 적용한다."],"rubric":[{"label":"개념 정확성","max":4},{"label":"원리·인과관계","max":3},{"label":"비교·적용","max":2},{"label":"논리적 구성","max":1}]},{"ex":[18],"title":"올바른 메모리 경고 설계","text":"VM의 여유 메모리가 기준 아래로 내려갈 때 통보하려는 경우 경고 규칙·작업 그룹·처리 규칙을 설명하세요.","answer":"대상 VM에서 가용 메모리 신호를 선택하고 최근 5분 평균이 2GiB 미만이라는 집계·단위·비교·임계값을 정한다. 가용량은 감소 방향이 부족을 뜻하며 사용량 증가 조건과 다르다. Action group으로 통보·대응을 연결하고 Alert processing rule로 유지보수 중 경고 억제 등을 관리한다. 각 측정값이 순간값인지 시간 구간의 집계값인지도 확인한다.","points":["대상·신호·논리·임계값","여유 값의 감소 방향","작업 그룹 통보·대응","처리 규칙과 검증"],"sourceIds":["DC-run-C07-3-ex18"],"locator":"직접 확인한 DataCamp 수업 / ex=18","claimId":"C07-3-expanded-9","contentType":"자체 작성 서술형 예상문제","id":"Q-C07-3-3","modelAnswer":"경고 규칙에서 대상 VM 범위와 사용 가능한 메모리 신호를 선택하고 기준 미만이라는 논리·임계값을 정한다. 여유 메모리가 부족한 상황은 값이 감소하는 방향이다. 통보나 연결된 대응은 작업 그룹으로 검토한다. 유지보수 중 경고 억제 등은 경고 처리 규칙의 역할이다. 조건 정의와 통보·억제·실제 조치를 구분하고 결과를 검증해야 한다.","version":"2026-10-16-expanded-v1","type":"자체 작성 서술형 예상문제","sourceLocator":"직접 확인한 DataCamp 수업 / ex=18","conceptIds":["C07-3-concept-5"],"objective":"메트릭·로그·분석·경고·조치·운영 정보를 연결한다.","expectedLength":"핵심 논점 중심 5~7문장","acceptedAlternatives":"동일한 개념·인과관계와 요구를 충족하는 대안 표현을 인정합니다. 서비스 이름만 같은 답은 충분하지 않습니다.","commonMistakes":["사용 가능한 메모리 부족은 값이 커지는 조건이며 경고 규칙만 만들면 메일이 간다."],"rubric":[{"label":"개념 정확성","max":4},{"label":"원리·인과관계","max":3},{"label":"비교·적용","max":2},{"label":"논리적 구성","max":1}]}]}},"supplements":[{"id":"review-cross","title":"AWS·Azure 통합 비교","chapterIds":[],"allCourses":true,"blocks":[{"type":"heading","text":"AWS · Azure 역할별 빠른 비교"},{"type":"table","headers":["목적","AWS","Azure","구분할 점"],"rows":[["가상 머신","EC2","Virtual Machines","OS·앱 구성과 운영 범위를 검토"],["함수 실행","Lambda","Functions","이벤트에 따른 코드 실행"],["객체 저장","S3","Blob Storage","파일·객체 보관. 블록·파일 저장과 구분"],["관계형 DB","RDS","SQL Database","관계형 구조와 SQL 요구"],["가상 네트워크","VPC","Virtual Network","주소·서브넷·연결·접근 통제를 구성"],["신원·접근 관리","IAM","Entra ID · Azure RBAC","인증과 리소스 권한 부여를 구분"],["배포·구성 자동화","CloudFormation","ARM templates · Bicep","IaC로 반복 가능한 구성을 정의"],["모니터링","CloudWatch","Azure Monitor","상태·메트릭·로그를 보고 운영을 조정"],["비용 계획·관찰","Pricing Calculator · Cost Explorer · Budgets","Pricing Calculator · Cost Management · Budgets","사전 추정·실제 분석·예산 알림을 구분"]]},{"type":"paragraph","text":"역할 대응은 목적을 비교하기 위한 것이다. 제품별 기능·설정·관리 범위까지 동일하다는 뜻은 아니다."},{"type":"heading","text":"자주 혼동하는 분류 축"},{"type":"table","headers":["구분","판단 기준","핵심 차이","적용"],"rows":[["서비스 모델","무엇을 제공받는가","IaaS / PaaS / SaaS","직접 통제할 범위와 운영 역량"],["배포 모델","누가 사용하고 어떻게 연결하는가","퍼블릭 / 프라이빗 / 하이브리드","공유·전용·환경 연결"],["멀티클라우드","업체가 몇 개인가","여러 제공업체 이용","하이브리드와 별개 기준"],["확장 방식","어떤 자원을 변경하는가","수직=한 대의 성능 / 수평=대수","병목과 앱 분산 가능성"],["인증 / 인가","누구인가 / 무엇을 할 수 있나","신원 확인 / 접근 허용","로그인 성공과 리소스 권한은 별개"],["가용성 / 복구","중단 대응 / 손상 이후 회복","중복·분산 / 백업·복원","복제와 백업의 목적을 분리"]]},{"type":"heading","text":"문제 조건에서 설계로 연결하는 흐름"},{"type":"paragraph","text":"<b>요구 파악 → 역할 분리 → 관리 범위 선택 → 데이터·네트워크 설계 → 접근 통제 → 관찰 → 용량·비용 조정.</b> 서비스 이름을 고르기 전에 처리·보관·조회·연결 중 필요한 역할과 데이터 특성을 먼저 확인한다."},{"type":"paragraph","text":"<b>갑작스러운 수요 증가:</b> 병목 확인 → 수직·수평 확장 비교 → 여러 자원으로 요청을 배분할 구조 검토 → 수요 감소 후 자원·비용 재검토."},{"type":"paragraph","text":"<b>민감한 데이터:</b> 데이터 분류·위치 요구 확인 → 인증·최소 권한 → 네트워크 접근 제한·암호화 → 로그와 정책으로 검증. 제공업체의 보호 기능이 고객의 데이터·권한 설정 책임을 없애지는 않는다."},{"type":"paragraph","text":"<b>비용 초과:</b> 실제 사용량·비용 분석 → 부서·프로젝트별 분류 → 유휴 자원·크기·가격 모델 검토 → 예산과 알림 설정 → 다시 측정. 예산 알림을 자원 자동 중단과 동일하게 설명하지 않는다."},{"type":"heading","text":"통합 서술형 문제 · 답안 예시"},{"type":"paragraph","text":"<b>문제.</b> 민감한 신청 데이터를 처리하는 웹 서비스가 행사 때 느려지고 비용도 증가한다. 클라우드 설계의 검토 순서를 서술하시오."},{"type":"paragraph","text":"<b>답안 예:</b> 먼저 요청 처리·파일 보관·데이터 조회 중 병목과 데이터 보호 요구를 파악한다. 직접 제어할 범위와 운영 역량으로 서비스 모델을 선택하고, 데이터 위치와 환경 연결로 배포 모델을 검토한다. 부하에는 수직·수평 확장과 요청 분산 구조를 비교한다. 인증·최소 권한·네트워크 제한·암호화를 적용하고 로그와 메트릭으로 검증한다. 사용량과 비용을 분석해 불필요한 자원과 가격 모델을 조정한다. 확장만으로 고가용성이나 비용 절감이 보장되는 것은 아니다."}]},{"title":"약어와 관리 책임 보강","blocks":[{"type":"heading","text":"AMI · 인스턴스 · 볼륨 · 접속 키의 차이"},{"type":"table","headers":["개념","뜻과 역할","연결되는 대상","구분할 것"],"rows":[["AMI","EC2 시작에 필요한 OS·소프트웨어 환경의 이미지","새 인스턴스의 시작 환경","실행 중인 서버 자체가 아님"],["인스턴스","클라우드에서 실행되는 가상 서버","코드 실행·요청 처리","이미지로 시작한 실제 실행 자원"],["인스턴스 유형","CPU·메모리 등 자원 특성의 조합","작업에 맞는 하드웨어 용량","AMI의 소프트웨어 구성과 별개"],["볼륨","인스턴스가 사용하는 저장 공간","OS·앱·데이터의 저장","컴퓨팅 처리 능력과 별개"],["키 페어","공개 키·개인 키 기반 접속 인증","예: SSH로 서버에 접속할 때 사용","트래픽 허용 규칙과 별개"],["보안 그룹","리소스의 수신·송신 트래픽 허용 규칙","네트워크 접근 허용","키를 보유해도 경로·허용 규칙이 필요"]]},{"type":"paragraph","text":"<b>생성 흐름:</b> 소프트웨어 환경을 AMI로 선택 → 작업 자원에 맞는 인스턴스 유형 선택 → 볼륨·네트워크·보안·접속 방법 구성 → 인스턴스 실행. 같은 AMI로 같은 소프트웨어 기반의 인스턴스를 여러 개 시작할 수 있다."},{"type":"heading","text":"서비스 모델별 관리 책임"},{"type":"table","headers":["영역","IaaS","PaaS","SaaS"],"rows":[["물리 서버·시설","제공업체","제공업체","제공업체"],["OS·기반 실행 환경","고객이 VM의 OS 등을 관리","제공업체가 기반 플랫폼 관리","제공업체가 서비스 기반 관리"],["앱·소프트웨어","고객이 설치·운영","고객은 앱 코드·설정, 업체는 플랫폼","업체는 완성 앱 운영, 고객은 이용 설정"],["데이터·사용자 계정","고객의 데이터 보호·권한 관리","고객의 데이터 보호·권한 관리","고객의 데이터 보호·권한 관리"],["네트워크 통제","고객이 가상 네트워크 접근 구성","업체 기반 보호와 고객 앱 접근 설정","업체 네트워크 보호, 고객 사용자 접근 설정"]]},{"type":"paragraph","text":"<b>IaaS:</b> 인프라를 빌려 쓰므로 OS 설정과 앱 설치의 통제 범위가 크다. 그만큼 패치·구성·운영 작업도 필요하다. <b>PaaS:</b> 기반 OS와 실행 플랫폼의 관리를 제공받고 앱 개발·배포에 집중한다. <b>SaaS:</b> 완성된 기능을 사용하지만 계정·공유 설정·데이터 이용 권한은 계속 관리한다."},{"type":"heading","text":"서술형 문제 · 답안 예시"},{"type":"paragraph","text":"<b>문제 1.</b> 같은 AMI를 사용하는 두 EC2 인스턴스의 처리 성능이 다를 수 있는 이유를 설명하시오."},{"type":"paragraph","text":"<b>답안 예:</b> AMI는 인스턴스를 시작할 소프트웨어 환경을 제공하고, 인스턴스 유형은 CPU·메모리 같은 자원 구성을 정한다. 따라서 같은 AMI로 시작해도 선택한 유형과 자원 크기가 다르면 처리 성능이 달라질 수 있다. 성능 문제는 이미지 이름만으로 판단하지 않고 CPU·메모리·저장 I/O의 실제 병목과 함께 분석한다."},{"type":"paragraph","text":"<b>문제 2.</b> SaaS를 도입해도 고객의 보안 책임이 남는 이유를 IaaS·PaaS와 비교하시오."},{"type":"paragraph","text":"<b>답안 예:</b> IaaS는 고객이 OS와 앱을 관리하며, PaaS는 기반 플랫폼을 제공받고 앱 코드·설정에 집중한다. SaaS는 완성된 앱 운영을 제공받아 직접 운영할 범위가 줄어든다. 하지만 어떤 데이터를 저장하고 누구에게 접근을 허용할지는 고객이 결정한다. 계정 해지·최소 권한·공유 설정과 데이터 보호는 SaaS에서도 필요한 작업이다."},{"type":"heading","text":"EC2 접속 방식의 조건 비교"},{"type":"table","headers":["방식","키·인바운드 포트","필요한 구성·접속 경로"],"rows":[["SSH 클라이언트","개인 키 관리 · 보통 22번 허용","로컬 터미널, 목적지까지의 경로·OS 사용자 확인"],["Session Manager","SSH 키·인바운드 SSH 개방 불필요","IAM 권한·SSM Agent·Systems Manager 연결 필요"],["Instance Connect","임시 공개 키 · SSH 포트 허용","콘솔·CLI 접근 권한과 SSH 네트워크 경로 필요"]]}],"id":"review-1","chapterIds":["C03-1"]},{"title":"네트워크 요청 흐름 보강","blocks":[{"type":"heading","text":"사용자 요청이 웹 서비스에 도달하는 흐름"},{"type":"paragraph","text":"<b>이름 확인 → 접속 경로 확보 → 트래픽 허용 여부 확인 → 요청 분배 → 앱 처리 → 데이터 조회 → 응답.</b> 아래는 AWS의 인터넷 공개 웹 서비스를 설명하는 구성 예다. DNS는 이름을 찾는 단계이며, 라우팅과 접근 통제는 실제 통신에 적용되는 서로 다른 역할이다."},{"type":"table","headers":["단계","구성요소","하는 일","확인할 조건"],"rows":[["1. 이름 해석","DNS · Route 53","서비스 도메인에 대응하는 접속 정보를 찾는다","이름과 목적지가 올바른가"],["2. 콘텐츠 전달","CDN · CloudFront","캐시된 콘텐츠를 가까운 위치에서 전달한다","필요한 콘텐츠에 적용했는가"],["3. 경로 구성","VPC · 서브넷 · 라우트 테이블 · 게이트웨이","주소 공간을 나누고 목적지로 보낼 경로를 정한다","인터넷 또는 사설 연결 경로가 있는가"],["4. 접근 통제","NACL · 보안 그룹","허용할 트래픽을 규칙으로 정한다","방향·출발지·목적지·포트가 맞는가"],["5. 요청 분배","로드 밸런서","실행 중인 여러 대상으로 요청을 분배한다","처리 대상이 정상인가"],["6. 앱·DB 처리","EC2 등 컴퓨팅 · DB","앱이 요청을 처리하고 필요한 데이터를 읽거나 기록한다","앱 실행·DB 연결·권한이 맞는가"]]},{"type":"paragraph","text":"<b>VPC와 서브넷:</b> VPC는 사설 네트워크 환경이며 서브넷은 그 안의 주소 공간을 나눈 단위다. AWS 서브넷은 하나의 가용 영역 안에 배치된다. 인터넷 게이트웨이로 향하는 경로가 있는 서브넷을 퍼블릭 서브넷이라고 한다. 서브넷 이름에 public을 붙이는 행위가 실제 경로를 만들지는 않는다."},{"type":"paragraph","text":"<b>직접 인터넷에 연결하는 IPv4 EC2의 예:</b> 인터넷 게이트웨이와 경로, 인스턴스의 공인 IPv4 주소, 접근 허용 규칙, 앱의 수신 상태가 함께 필요하다. 공인 IP 하나만 부여하거나 보안 규칙 하나만 추가하는 것으로 전체 연결이 완성되는 것은 아니다. 프라이빗 앱을 공개 로드 밸런서 뒤에 두는 구조와 직접 공개하는 구조도 구분한다."},{"type":"heading","text":"Azure 연결 방식 · 수신과 송신을 구분하기"},{"type":"table","headers":["목적","방식","역할·조건"],"rows":[["인터넷에서 서비스 접속","공개 엔드포인트·공인 IP","인증과 방화벽 규칙은 별도로 구성"],["VNet에서 PaaS 사설 접속","Private Endpoint","VNet의 사설 IP로 서비스에 연결"],["VM에서 인터넷으로 송신","NAT Gateway","VM별 공인 IP 없이 송신 구성. 외부의 임의 수신과 다름"],["App Service에서 VNet 자원 호출","VNet Integration","앱에서 VNet 방향의 송신 연결"]]},{"type":"paragraph","text":"<b>네트워크 간 연결:</b> VNet Peering은 Azure VNet끼리, VPN Gateway는 인터넷 위 암호화 터널로 기관망과 VNet을 연결한다. ExpressRoute는 공용 인터넷을 우회하는 사설 연결이며 암호화는 별도로 검토한다."},{"type":"heading","text":"서술형 문제 · 답안 예시"},{"type":"paragraph","text":"<b>문제 1.</b> EC2에 공인 IP를 부여했는데 접속이 안 된다. 확인할 항목을 역할별로 서술하시오."},{"type":"paragraph","text":"<b>답안 예:</b> 먼저 DNS가 올바른 목적지를 가리키는지 확인한다. 인스턴스가 속한 서브넷의 라우팅과 인터넷 게이트웨이 연결을 검토하고, NACL과 보안 그룹에서 해당 출발지·방향·포트를 허용하는지 확인한다. 이후 웹 서버가 실행되고 올바른 포트에서 요청을 받는지 확인한다. 공인 IP는 주소 조건이며 경로·접근 통제·앱 실행을 대신하지 않는다."},{"type":"paragraph","text":"<b>문제 2.</b> 요청 지연 문제에서 로드 밸런서·Auto Scaling·CDN의 역할을 구분하시오."},{"type":"paragraph","text":"<b>답안 예:</b> 로드 밸런서는 요청을 여러 실행 대상으로 나누고 Auto Scaling은 수요에 맞게 대상 수를 조정한다. CDN은 캐시 가능한 콘텐츠를 사용자 가까이에서 전달하여 원본 요청과 전달 지연을 줄이는 데 쓰인다. 세 기능의 조정 대상이 다르므로 먼저 요청 집중·전체 처리 용량·콘텐츠 전달 중 어느 부분이 병목인지 구분한다."}],"id":"review-2","chapterIds":["C03-2","C06-2"]},{"title":"저장과 데이터 서비스 선택 보강","blocks":[{"type":"heading","text":"객체 · 블록 · 파일 저장을 고르는 기준"},{"type":"table","headers":["유형","접근 방식과 원리","서비스 예","적합한 상황"],"rows":[["객체","데이터와 메타데이터를 객체로 보관하고 키·API로 접근","S3 · Blob Storage","사진·문서·로그 파일 등 객체 보관"],["블록","저장 공간을 블록 단위 볼륨으로 제공하며 OS가 파일시스템 등을 사용","EBS · Managed Disks","VM의 OS·앱용 디스크"],["파일","디렉터리·파일 경로를 통해 접근하고 공유 파일시스템으로 사용","EFS · Azure Files","여러 작업이 파일 경로로 같은 파일에 접근"],["캐시","자주 접근하는 데이터의 복사본을 빠르게 제공","ElastiCache 등","반복 조회 지연과 원본 부하 감소"]]},{"type":"paragraph","text":"<b>판단 순서:</b> 데이터 종류보다 앱이 어떻게 읽고 쓰는지부터 본다. 이미지라도 객체 API를 쓰는 웹 앱과 파일 경로를 요구하는 기존 앱은 적합한 접근 방식이 다를 수 있다. VM 디스크, 공유 파일, 객체 보관의 인터페이스와 공유 요구를 구분하고 성능·보관 기간·비용을 비교한다."},{"type":"paragraph","text":"<b>보관 계층:</b> 자주 읽는 데이터와 오래 보관하며 드물게 읽는 데이터는 접근 패턴이 다르다. AWS 저장 클래스와 Azure Hot·Cool·Archive 등을 검토할 때 저장료만 보지 않고 검색·복원 시간과 접근 비용을 함께 본다. 장기 보관 계층으로 옮기는 결정과 백업 복원 계획은 별개다."},{"type":"heading","text":"관계형 · NoSQL · 캐시를 고르는 기준"},{"type":"table","headers":["대상","데이터·접근 요구","서비스 예","선택 근거"],"rows":[["관계형 DB","표와 관계, SQL 질의, 트랜잭션 요구","RDS · Azure SQL Database","주문·결제 등 관계와 일관된 갱신이 중요한 데이터"],["키 기반 NoSQL","정해진 키·접근 패턴 중심의 조회","DynamoDB","키 중심 요청이 많은 서비스에서 모델 적합성 검토"],["다양한 NoSQL 모델","문서 등 필요한 모델과 접근 방식","Cosmos DB 등","데이터 구조·질의·분산 요구를 함께 비교"],["캐시","반복 조회 결과의 빠른 재사용","ElastiCache 등","원본 DB를 대체하기보다 반복 읽기 부담 완화"],["분석용 저장·질의","대량 데이터의 집계·분석","Redshift · Athena 등","운영 거래 처리와 분석 목적을 구분"]]},{"type":"paragraph","text":"<b>관계형과 NoSQL:</b> 단순히 데이터 양이 많다는 이유만으로 NoSQL을 고르지 않는다. 관계·질의·트랜잭션과 키 기반 접근, 데이터 모델·확장 요구를 기준으로 비교한다. NoSQL도 제품별 기능이 다르므로 모두 같은 구조이거나 트랜잭션이 전혀 없다고 외우지 않는다."},{"type":"heading","text":"서술형 문제 · 답안 예시"},{"type":"paragraph","text":"<b>문제 1.</b> 쇼핑몰의 상품 이미지·주문 내역·VM 디스크·여러 서버의 공유 파일·반복 조회를 각각 어떻게 분리할지 설명하시오."},{"type":"paragraph","text":"<b>답안 예:</b> 상품 이미지는 객체 저장인 S3 또는 Blob Storage, 주문 내역은 관계와 트랜잭션 요구를 검토해 관계형 DB를 선택한다. VM 디스크에는 EBS나 Managed Disks 같은 블록 저장을 사용한다. 앱이 파일 경로로 공유 파일에 접근해야 한다면 EFS나 Azure Files를 비교한다. 반복 조회에는 캐시를 검토하되 갱신 시점과 원본 데이터의 일치도도 함께 관리한다."},{"type":"paragraph","text":"<b>문제 2.</b> 고객이 늘어 조회가 느려졌다는 이유만으로 관계형 DB를 NoSQL로 바꾸는 결정이 충분하지 않은 이유를 쓰시오."},{"type":"paragraph","text":"<b>답안 예:</b> 지연 원인이 DB 모델인지, 질의나 자원·접근 패턴인지 먼저 확인해야 한다. 관계형 DB가 제공하는 관계와 트랜잭션이 업무에 필요한지도 검토한다. 키 중심 접근이 요구에 맞으면 NoSQL을 비교할 수 있고 반복 읽기에는 캐시가 대안이 될 수 있다. 선택은 사용자 수 하나가 아니라 데이터 구조·질의·일관성·운영 부담과 비용을 근거로 설명한다."}],"id":"review-3","chapterIds":["C02-3","C03-2","C05-2","C06-1"]},{"title":"가용성과 복구 보강","blocks":[{"type":"heading","text":"고가용성 · 복제 · 백업 · 재해 복구의 차이"},{"type":"table","headers":["개념","해결하려는 문제","주요 방식","남는 과제"],"rows":[["고가용성","일부 구성요소 장애로 서비스가 멈추는 문제","중복 구성·분산 배치·장애 전환","대체 자원의 용량과 연결도 준비"],["복제","다른 위치에도 데이터 사본이 필요한 문제","변경 내용을 다른 사본에 반영","삭제·오류가 사본에도 반영될 수 있음"],["백업","삭제·손상 이전의 데이터로 돌아갈 필요","복구 가능한 시점의 사본을 보관","보관 주기·권한·복원 절차와 테스트"],["재해 복구","주요 운영 환경을 사용할 수 없는 큰 장애","대체 환경·데이터·전환·복귀 절차","앱·신원·네트워크·데이터를 함께 회복"],["모니터링","상태 변화나 이상을 알아야 하는 문제","메트릭·로그·경고","탐지 이후 실제 조치가 필요"]]},{"type":"paragraph","text":"<b>왜 복제와 백업을 함께 고려하는가?</b> 복제는 사본을 유지해 장애 대응에 도움을 주지만, 잘못된 변경이 전파되면 현재 사본만으로 이전 상태를 찾기 어렵다. 백업은 보관한 시점으로 복원하는 역할이다. 사본의 수만 세지 말고 어떤 장애·삭제·손상에서 어느 상태로 돌아갈지 구분한다."},{"type":"heading","text":"장애 범위에 맞는 배치와 데이터 보호"},{"type":"table","headers":["범위·방식","핵심 역할","대응하는 상황","확인할 점"],"rows":[["가용 영역 분산","같은 리전의 분리된 영역에 배치","한 영역의 장애에 대응","앱과 데이터가 함께 대응 가능한가"],["리전 분산","지리적으로 분리된 리전에 구성","리전 범위의 큰 장애에 대비","데이터 이동·위치 요구·전환 절차"],["LRS","한 데이터센터 내 로컬 복제","로컬 하드웨어 장애 대응","영역·리전 분산과 구분"],["ZRS","리전 내 가용 영역에 분산 복제","영역 장애 대응","지역·서비스 조건 검토"],["GRS / GZRS","보조 리전 복제 / 영역과 리전 조합","리전 장애 대비","사본과 즉시 접근·전환 가능성은 구분"],["Azure Backup / Site Recovery","데이터 백업·복원 / 워크로드 복제·전환","데이터 손상 / 운영 환경 장애","목적에 맞는 복구 도구 선택"]]},{"type":"paragraph","text":"<b>복구 흐름:</b> 장애 탐지 → 영향 범위와 데이터 상태 확인 → 정상 사본으로 전환할지 이전 백업을 복원할지 결정 → 컴퓨팅·네트워크·신원·데이터 연결 복구 → 앱 기능과 데이터 검증 → 운영 재개 → 원인 분석·절차 개선."},{"type":"heading","text":"처리 용량 확장과 장애 분산"},{"type":"table","headers":["선택","목적","구성·원리"],"rows":[["Scale Set","VM 수량·처리 용량 조정","확장 규칙으로 VM 대수 조정"],["Availability Set","장비·계획 유지보수 영향 분산","Fault Domain=장비 장애 / Update Domain=유지보수"],["Availability Zone","영역 단위 장애 영향 분산","같은 리전의 물리적으로 분리된 영역에 배치"]]},{"type":"heading","text":"서술형 문제 · 답안 예시"},{"type":"paragraph","text":"<b>문제 1.</b> 데이터를 여러 위치에 복제했어도 백업이 필요한 이유를 설명하시오."},{"type":"paragraph","text":"<b>답안 예:</b> 복제는 다른 위치에 사본을 유지해 하드웨어나 위치 장애에 대응하는 데 도움을 준다. 그러나 잘못된 삭제나 데이터 손상이 사본에도 반영될 수 있다. 백업은 보관한 과거 시점의 데이터를 복원하는 데 쓰이므로 현재 사본 유지와 목적이 다르다. 보관 정책과 복원 절차를 정하고 실제 복원 결과를 시험해야 한다."},{"type":"paragraph","text":"<b>문제 2.</b> 여러 서버에 앱을 배치하고 자동 확장을 구성했다면 재해 복구 준비가 끝났다고 할 수 있는가?"},{"type":"paragraph","text":"<b>답안 예:</b> 여러 서버와 자동 확장은 요청 분산과 처리 용량 조정에 도움이 되지만, 같은 장애 범위에 있거나 데이터가 손상되면 서비스 전체에 문제가 생길 수 있다. 장애 범위에 맞는 영역·리전 배치, 데이터 복제와 백업, 접근 권한·네트워크·앱을 함께 회복할 절차가 필요하다. 전환 후 데이터와 기능을 검증하고 실제 복구 연습으로 준비 상태를 확인한다."}],"id":"review-4","chapterIds":["C06-1","C06-2"]},{"title":"보안 규칙과 가격 모델","blocks":[{"type":"heading","text":"보안 그룹 · NACL의 규칙과 응답 처리"},{"type":"table","headers":["비교 기준","보안 그룹 Security group","네트워크 ACL NACL"],"rows":[["적용 범위","연결된 리소스의 네트워크 인터페이스·인스턴스 수준","연결된 서브넷 수준"],["규칙 유형","허용 규칙. 명시적인 거부 규칙은 없음","허용·거부 규칙"],["규칙 평가","적용되는 허용 규칙들을 종합","낮은 규칙 번호부터 확인하고 처음 일치한 규칙 적용"],["상태 추적","Stateful. 허용한 통신의 응답은 상태에 따라 자동 허용","Stateless. 요청과 응답을 각각 규칙으로 허용해야 함"],["설계 초점","해당 리소스에 필요한 통신을 허용","서브넷 경계에서 추가 통제"]]},{"type":"paragraph","text":"<b>응답 예:</b> 외부에서 웹 서버로 들어오는 요청이 보안 그룹에서 허용되었다면 그 요청의 응답은 상태 추적에 따라 허용된다. NACL은 상태를 추적하지 않으므로 들어오는 요청뿐 아니라 반대 방향의 응답도 허용 규칙을 확인해야 한다. 웹 서버의 수신 포트와 클라이언트가 응답을 받는 포트를 같은 것으로 가정하지 않는다."},{"type":"paragraph","text":"<b>원인 분리:</b> 경로 없음은 라우팅, 트래픽 차단은 보안 그룹·NACL, 작업 권한 부족은 IAM, 요청 처리 실패는 앱·DB 설정을 확인한다. 네트워크 규칙과 OS 방화벽도 별개이므로 리소스 접근을 한 가지 규칙만으로 설명하지 않는다."},{"type":"heading","text":"수요와 중단 허용 여부로 가격 모델 선택하기"},{"type":"table","headers":["선택","요금·약정의 성격","적합한 상황","주요 판단"],"rows":[["On-Demand","장기 사용 약정 없이 필요에 따라 사용","초기 실험·예측 어려운 단기 수요","유연성과 실제 사용료"],["Reserved Instances","일정한 인스턴스 구성 사용을 약정하는 할인 방식","장기간 예측 가능한 기본 수요","구성·기간·활용도. 용량 예약 여부는 조건별 구분"],["Savings Plans","시간당 일정 사용 금액을 약정하는 할인 방식","지속적인 사용량이 있고 적용 범위가 맞는 경우","사용 금액 약정과 대상·유연성"],["Spot","유휴 용량을 활용하며 중단될 수 있음","재시도·중단이 가능한 배치 작업","중단 대응·체크포인트·재처리"]]},{"type":"paragraph","text":"<b>선택 흐름:</b> 실제 수요 측정 → 상시 기본 수요와 일시적 피크 분리 → 중단 허용 여부 확인 → 약정의 활용 가능성과 할인 조건 비교 → 운영 후 사용량 재검토. 가격 모델은 비용 조건이고 인스턴스 유형은 자원 특성이므로 서로 다른 선택 축이다."},{"type":"paragraph","text":"<b>조합 예:</b> 계속 운영하는 기본 부하는 예약·약정의 적용을 검토하고, 행사 때만 늘어나는 추가 부하는 On-Demand로 대응할 수 있다. 중단 후 이어서 처리할 수 있는 야간 변환 작업은 Spot 후보가 된다. 저렴한 단가보다 실제 활용률과 중단에 따른 재작업 비용을 함께 비교한다."},{"type":"heading","text":"Azure VM 상태별 과금과 계산 예시"},{"type":"table","headers":["VM 상태","컴퓨팅 사용 요금","확인할 점"],"rows":[["Running","발생","접속자가 없어도 실행 상태"],["Stopped (Allocated)","발생","OS 종료 후에도 호스트 자원은 할당됨"],["Deallocated","발생하지 않음","디스크·일부 네트워크 등 별도 요금은 남을 수 있음"]]},{"type":"paragraph","text":"<b>월 비용 = 시간당 단가 × 과금 시간 + 기타 비용.</b> 수업의 가상 단가 200원/시간, 기타 비용 20,000원으로 계산하면 160시간은 52,000원, 720시간은 164,000원이다. 차이는 112,000원이다. 이는 실제 Azure 가격이 아니며 비사용 시간에 할당 해제한 조건의 계산이다. OS 종료와 할당 해제를 구분해야 시간 단축 효과를 설명할 수 있다."}],"id":"review-5","chapterIds":["C04-2","C04-3","C07-2"]},{"title":"Azure 계층과 이벤트 흐름","blocks":[{"type":"heading","text":"Azure 관리 계층 · 범위와 상속"},{"type":"paragraph","text":"<b>관리 그룹 → 구독 → 리소스 그룹 → 리소스.</b> 상위 범위에서 할당한 역할과 정책은 하위 범위에 적용될 수 있다. 할당 위치는 필요한 작업 범위에 맞춘다. 관리 계층과 리전·가용 영역의 물리 배치는 다른 기준이다."},{"type":"table","headers":["계층","묶는 대상·역할","적용 예","구분할 점"],"rows":[["관리 그룹","여러 구독을 묶는 상위 관리 범위","여러 구독에 공통 정책 적용","서버를 실행하는 위치 아님"],["구독 Subscription","자원 사용·청구와 접근 관리의 경계","개발·운영의 비용과 권한 구분","계정·사용자와 같은 뜻 아님"],["리소스 그룹","관련 자원의 수명 주기를 묶는 논리적 컨테이너","웹 앱과 관련 자원을 함께 관리","네트워크 서브넷과 다름"],["리소스 Resource","생성·관리하는 구체적인 인스턴스","VM·저장 계정·가상 네트워크","기능 범주인 서비스와 구분"]]},{"type":"heading","text":"RBAC · Policy · Lock · Tag의 역할"},{"type":"table","headers":["도구","핵심 질문","예시","설계 기준"],"rows":[["Azure RBAC","누가 어느 범위에서 무엇을 할 수 있나?","운영팀에 특정 그룹의 관리 역할 부여","주체·역할·범위, 최소 권한"],["Azure Policy","리소스가 어떤 기준을 충족해야 하나?","허용 리전·필수 태그의 기준 평가","효과에 따라 감사·거부·수정 등을 구분"],["Resource Lock","관리 작업 중 어떤 변경을 제한하나?","CanNotDelete로 삭제 방지","관리 작업과 데이터 작업을 구분"],["Tag","어떤 분류·담당·비용 단위에 속하나?","department=finance로 비용 분류","분류 메타데이터이며 권한 부여 수단 아님"]]},{"type":"paragraph","text":"<b>적용 예:</b> 팀의 VM 관리 작업은 RBAC, 배포 가능 지역은 Policy, 실수로 인한 삭제 방지는 Lock, 부서별 비용 분류는 Tag로 나눈다. RBAC 권한이 있어도 Policy의 제한과 Lock의 적용을 함께 확인해야 한다. 태그가 있다고 접근 권한이 생기거나 모든 하위 자원에 자동 상속된다고 가정하지 않는다."},{"type":"heading","text":"EventBridge · SQS · SNS를 주문 흐름으로 연결"},{"type":"table","headers":["서비스","핵심 역할","주문 처리 예","다른 역할과 구분"],"rows":[["EventBridge","이벤트를 조건에 맞는 대상으로 라우팅","주문 생성 사건을 규칙에 맞춰 전달","처리 작업을 쌓는 큐 자체와 다름"],["SQS","소비자가 처리할 메시지를 큐에 보관","처리할 주문을 쌓고 작업자가 가져감","처리 대기와 생산자·소비자 분리"],["SNS","발행한 메시지를 구독 대상으로 전달","주문 결과를 여러 구독자에 통보","여러 대상으로 배포하는 목적"]]},{"type":"paragraph","text":"<b>구성 예:</b> 주문 생성 → EventBridge가 대상 규칙에 따라 전달 → SQS에 처리 작업 대기 → 작업자가 주문 처리 → 결과를 SNS로 구독자에게 통보. 목적에 따라 일부만 조합할 수도 있다. 큐를 쓰면 순간적인 요청 증가와 처리 속도를 분리할 수 있으며 재시도·중복 처리에 대한 앱 설계도 필요하다."},{"type":"heading","text":"RBAC 역할과 권한 축소 사례"},{"type":"table","headers":["역할","허용하는 일","구분할 점"],"rows":[["Reader","자원의 관리 정보 조회","자원 변경·Blob 데이터 읽기와 별개"],["Contributor","자원 생성·변경·삭제","Azure 역할 할당 권한은 없음"],["Owner","자원 관리와 접근 권한 부여","넓은 권한이므로 범위를 제한"],["Storage Blob Data Reader","Blob 데이터 읽기","일반 Reader와 다른 데이터 접근 역할"]]},{"type":"paragraph","text":"<b>권한 축소:</b> 구독 Contributor는 하위 자원에도 적용된다. 특정 그룹에 Reader를 추가해도 상위의 Contributor가 유지된다. 원래 역할을 할당한 범위에서 넓은 권한을 제거·재설계하고 필요한 그룹·자원에 최소 권한으로 재할당한다. 낮은 역할 추가와 기존 권한 회수는 다른 작업이다."}],"id":"review-6","chapterIds":["C03-3","C06-3","C07-1"]}],"priorityQuestions":{"C01-1":[0],"C01-2":[1],"C02-1":[1],"C02-2":[2],"C03-1":[1],"C03-2":[2],"C03-3":[1],"C04-1":[0],"C04-2":[0],"C04-3":[0],"C05-1":[0],"C05-2":[0],"C06-1":[2],"C06-2":[0],"C06-3":[1],"C07-1":[1],"C07-2":[0],"C07-3":[2]}};
